def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def safe_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            a, b = x[0], x[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return [int(a), int(b)]
        return None

    def safe_points(v):
        if not isinstance(v, (list, tuple)):
            return []
        out = []
        for item in v:
            p = safe_pos(item)
            if p is not None:
                out.append(p)
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def choose_best(points, src, prefer_far=False):
        if not points:
            return None
        best = points[0]
        best_score = manhattan(src, best)
        for p in points[1:]:
            s = manhattan(src, p)
            if (prefer_far and s > best_score) or ((not prefer_far) and s < best_score):
                best, best_score = p, s
        return best

    obs = observation if isinstance(observation, dict) else {}
    env = obs.get("environment_name", "resource_collection")
    self_pos = safe_pos(obs.get("self_position")) or [0, 0]
    opp_pos = safe_pos(obs.get("opponent_position"))
